js-codebreaker:
// Vergleiche erst die Positionen, dann die übrigen passenden Ziffern.
const digits = "0123456789".split("");
let secret = "";
for (let i = 0; i < 4; i++) {
  secret += digits.splice(Math.floor(Math.random() * digits.length), 1)[0];
}
console.log("Codebreaker: Vier verschiedene Ziffern von 0 bis 9.");
console.log("Richtige Position = Ziffer und Platz stimmen.");
console.log("Andere Position = Ziffer stimmt, Platz stimmt nicht.");
console.log("Beginne z. B. mit 0123. Nutze dann die Rückmeldungen.");
let attempt = 1;
let feedback = "Beginne z. B. mit 0123.";
let solved = false;
while (attempt <= 10) {
  const input = prompt(`Versuch ${attempt}/10: Vier verschiedene Ziffern.
${feedback}`);
  if (input === null) {
    console.log("Abgebrochen.");
    return;
  }
  const guess = input.trim();
  if (!/^[0-9]{4}$/.test(guess)) {
    feedback = "Bitte genau 4 Ziffern (0–9) eingeben. Kein Versuch verbraucht.";
    console.log(feedback);
    continue;
  }
  if (new Set(guess).size !== 4) {
    feedback = "Keine Ziffer darf doppelt vorkommen. Kein Versuch verbraucht.";
    console.log(feedback);
    continue;
  }
  let correctPosition = 0;
  let correctDigit = 0;
  for (let i = 0; i < 4; i++) {
    if (guess[i] === secret[i]) correctPosition++;
    if (secret.includes(guess[i])) correctDigit++;
  }
  correctDigit -= correctPosition;
  console.log("Tipp:", guess);
  if (guess === secret) {
    console.log("CODE GEKNACKT!");
    solved = true;
    break;
  }
  console.log("Richtige Position:", correctPosition);
  console.log("Richtige Ziffer, falsche Position:", correctDigit);
  feedback = `Tipp ${guess}: ${correctPosition} richtige Position; ${correctDigit} richtige Ziffer an anderer Position.`;
  attempt++;
}
if (!solved) console.log("Verloren! Der Code war:", secret);

