js-drag-circles:
// Drücken wählt einen Kreis; Bewegen verschiebt ihn; Loslassen beendet das Ziehen.
const canvas = graphics.canvas({title: "Formen", width: 600, height: 360});
const ctx = canvas.getContext("2d");

const circles = [{x: 180, y: 180, color: "purple"},
                 {x: 420, y: 180, color: "orange"}];
const radius = 36;
let selected = null;
function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (const c of circles) {
    ctx.fillStyle = c.color;
    ctx.beginPath(); ctx.arc(c.x, c.y, radius, 0, 2*Math.PI); ctx.fill();
  }
}
function point(event) {
  const box = canvas.getBoundingClientRect();
  return {x: (event.clientX-box.left)*canvas.width/box.width,
          y: (event.clientY-box.top)*canvas.height/box.height};
}
canvas.addEventListener("pointerdown", event => {
  if (event.button !== 0) return;
  const p = point(event);
  selected = circles.find(c => Math.hypot(c.x-p.x, c.y-p.y) <= radius);
  if (selected) canvas.setPointerCapture(event.pointerId);
});
canvas.addEventListener("pointermove", event => {
  if (!selected) return;
  const p = point(event);
  selected.x = Math.max(radius, Math.min(canvas.width-radius, p.x));
  selected.y = Math.max(radius, Math.min(canvas.height-radius, p.y));
  draw();
});
function release() { selected = null; }
canvas.addEventListener("pointerup", release);
canvas.addEventListener("pointercancel", release);
draw();
console.log("Ziehe einen Kreis mit der Maus oder dem Finger.");

