js-bouncing-ball:
// canvas.animate() liefert den Zeitschritt dt; Schwerkraft und Bewegung nutzen ihn.
const canvas = graphics.canvas({title: "Formen", width: 600, height: 360});
const ctx = canvas.getContext("2d");

const radius = 21;
let x = 300, y = canvas.height-radius, velocity = 0, holding = false;
function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.strokeStyle = "gray";
  ctx.beginPath(); ctx.moveTo(0, canvas.height-1);
  ctx.lineTo(canvas.width, canvas.height-1); ctx.stroke();
  ctx.fillStyle = "royalblue";
  ctx.beginPath(); ctx.arc(x, y, radius, 0, 2*Math.PI); ctx.fill();
}
function point(event) {
  const box = canvas.getBoundingClientRect();
  return {x: (event.clientX-box.left)*canvas.width/box.width,
          y: (event.clientY-box.top)*canvas.height/box.height};
}
canvas.addEventListener("pointerdown", event => {
  const p = point(event);
  if (event.button === 0 && Math.hypot(x-p.x, y-p.y) <= radius) {
    holding = true; velocity = 0;
    canvas.setPointerCapture(event.pointerId);
  }
});
canvas.addEventListener("pointermove", event => {
  if (!holding) return;
  const p = point(event);
  x = Math.max(radius, Math.min(canvas.width-radius, p.x));
  y = Math.max(radius, Math.min(canvas.height-radius, p.y));
  draw();
});
function release() { holding = false; }
canvas.addEventListener("pointerup", release);
canvas.addEventListener("pointercancel", release);
canvas.animate(dt => {
  if (holding) return;
  velocity += 588 * dt; // Pixel-Koordinaten: nach unten positiv.
  y += velocity * dt;
  if (y > canvas.height-radius) {
    y = canvas.height-radius;
    velocity = -velocity * 0.75;
    if (Math.abs(velocity) < 30) velocity = 0;
  }
  draw();
});
draw();
console.log("Ziehe den Ball hoch und lasse ihn los: Er fällt und springt.");

