// Die Definition beschreibt die Arbeit; erst der Aufruf führt sie aus.
function say_hello() {
  console.log("Hallo!");
}
say_hello();
say_hello();

js-basics-greet-person:
// Der Parameter erhält bei jedem Aufruf den übergebenen Wert.
function greet(name) {
  console.log("Hallo,", name);
}
greet("Alex");
greet("Sam");

js-basics-rectangle-area:
// return liefert das Ergebnis; der Aufrufer entscheidet über die Ausgabe.
function area(width, height) {
  return width * height;
}
console.log(area(3, 4));
console.log(area(2, 5));
